// Normalisasi data dari webhook agar konsisten sebelum disimpan & diklasifikasi.
const input = $json.body ?? $json;

const clean = (value) => String(value ?? "").trim();

const name = clean(input.name);
const email = clean(input.email).toLowerCase();
let whatsapp = clean(input.whatsapp || input.phone).replace(/[^\d+]/g, "");

if (whatsapp.startsWith("+62")) whatsapp = "62" + whatsapp.slice(3);
else if (whatsapp.startsWith("0")) whatsapp = "62" + whatsapp.slice(1);
else if (whatsapp.startsWith("8")) whatsapp = "62" + whatsapp;

const message = clean(input.message);

if (!name || (!email && !whatsapp) || message.length < 10) {
  throw new Error("Data lead tidak lengkap: butuh nama, email/WhatsApp, dan pesan minimal 10 karakter.");
}

const leadId = "LD-" + Date.now().toString(36).toUpperCase() + "-" + Math.random().toString(36).slice(2, 6).toUpperCase();

return [{
  json: {
    lead_id: leadId,
    created_at: new Date().toISOString(),
    name,
    email,
    whatsapp,
    company: clean(input.company),
    source: clean(input.source) || "website",
    budget: clean(input.budget),
    message,
    consent: input.consent === true || input.consent === "true",
    status: "new"
  }
}];

