// Ambil data lead asli dan hasil klasifikasi AI, lalu gabungkan dengan fallback aman.
let lead;
try {
  lead = $("Normalisasi Lead").item.json;
} catch (error) {
  lead = $json;
}

const raw =
  $json.message?.content ??
  $json.content ??
  $json.text ??
  $json.choices?.[0]?.message?.content ??
  "{}";

let ai = {};
try {
  const text = typeof raw === "string" ? raw : JSON.stringify(raw);
  const match = text.match(/\{[\s\S]*\}/);
  ai = JSON.parse(match ? match[0] : text);
} catch (error) {
  ai = {};
}

const allowed = ["high", "medium", "low"];
const priority = allowed.includes(ai.priority) ? ai.priority : "medium";
const fallbackScore = priority === "high" ? 85 : priority === "medium" ? 55 : 25;
const score = Math.max(0, Math.min(100, Number(ai.score) || fallbackScore));

const replyDraft = ai.reply_draft || `Halo ${lead.name}, terima kasih sudah menghubungi kami. Kami sudah menerima kebutuhan Anda dan tim kami akan menghubungi Anda dalam 1x24 jam pada jam kerja.`;
const followupDraft = ai.followup_draft || `Halo ${lead.name}, kami ingin menindaklanjuti pesan Anda sebelumnya. Apakah masih ada yang bisa kami bantu? Kami siap mengatur demo singkat sesuai kebutuhan ${lead.company || "bisnis Anda"}.`;

return [{
  json: {
    ...lead,
    priority,
    score,
    intent: ai.intent || "general_inquiry",
    summary: ai.summary || lead.message.slice(0, 160),
    reply_draft: replyDraft,
    followup_draft: followupDraft,
    ai_model: ai.model || "gpt-4o-mini",
    classified_at: new Date().toISOString()
  }
}];

